[ExtensionOf(classstr(TAMRebatePostContract))]
final class METTAMRebatePostContract_Extension
{
    public boolean isCalledFromMainBatchJob = true;

    // Bug 340352: [MS] E2E - RE-0031 Vendor Rebate - Batch Job Failed for Posting. MS SR# - 2603010030001346
    private boolean metShowAutoSetDate;
    private METAutoSetDate metAutoSetDate;
    private boolean initiatePrintInvoice = true;


}

Method.Source:
/// <summary>
/// CB705_Rebate batch jobs & Vendor payback extension used to store identifier for caller object 
/// </summary>
/// <param name = "_isCalledFromMainBatchJob">isCalledFromMainBatchJob</param>
/// <returns>boolean</returns>
public boolean parmIsCalledFromMainBatchJob(boolean _isCalledFromMainBatchJob = isCalledFromMainBatchJob)
{
    isCalledFromMainBatchJob = _isCalledFromMainBatchJob;
    return isCalledFromMainBatchJob;
}

/// <summary>
/// Show auto date population option in UI or not.
/// </summary>
/// <param name = "_metShowAutoSetDate">boolean</param>
/// <returns>True if visible; otherwise, false.</returns>
[DataMember, SysOperationControlVisibility(false)]
public boolean metParmShowAutoSetDate(boolean _metShowAutoSetDate = metShowAutoSetDate)
{
    metShowAutoSetDate = _metShowAutoSetDate;

    return metShowAutoSetDate;
}

/// <summary>
/// Auto date population
/// </summary>
/// <param name = "_metAutoSetDate">METAutoSetDate</param>
/// <returns>True if auto date population; otherwise, false.</returns>
[
    DataMember,
    SysOperationDisplayOrder('4'),
    SysOperationGroupMember('Period')
]
public METAutoSetDate metParmAutoSetDate(METAutoSetDate _metAutoSetDate = metAutoSetDate)
{
    metAutoSetDate = _metAutoSetDate;

    return metAutoSetDate;
}

/// <summary>
/// Initiate Print Invoice to be displayed on UI.
/// </summary>
/// <param name = "metInitiatePrintInvoice">boolean</param>
/// <returns>True if visible; otherwise, false.</returns>
[DataMember, SysOperationLabel(literalStr("@MET:InitiatePrintInvoice"))]
public boolean parmInitiatePrintInvoice(boolean _initiatePrintInvoice = initiatePrintInvoice)
{
    initiatePrintInvoice = _initiatePrintInvoice;

    return initiatePrintInvoice;
}
